workedExamples.code:
#include <iostream>
int main() {
    int n;
    if (!(std::cin >> n)) { std::cout << "invalid\n"; return 0; }
    if (n % 2 == 0) std::cout << "even\n";
    else std::cout << "odd\n";
}

#include <iostream>
int main() {
    int n;
    if (!(std::cin >> n) || n < 0 || n > 10000) {
        std::cout << "invalid\n";
        return 0;
    }
    int sum = 0;
    for (int k = 1; k <= n; ++k) {
        if (k % 2 == 0) sum += k;
    }
    std::cout << sum << '\n';
}

